package info.aalmoghalis.inventory;
import android.content.SharedPreferences;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;
public final class SettingsActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);SharedPreferences p=getSharedPreferences("settings",0);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);TextView h=new TextView(this);h.setText("إعـدادات");h.setTextSize(20);h.setGravity(17);h.setPadding(10,18,10,18);r.addView(h);add(r,"اسم المستخدم","prefUsername",p);add(r,"العنوان","prefAddress",p);add(r,"الهاتف","prefPhone",p);add(r,"الرقم الضريبي","prefTax_no",p);CheckBox backup=new CheckBox(this);backup.setText("النسخ الاحتياطي التلقائي");backup.setChecked(p.getBoolean("prefAutoBackup",true));r.addView(backup);backup.setOnCheckedChangeListener((v,c)->p.edit().putBoolean("prefAutoBackup",c).apply());CheckBox login=new CheckBox(this);login.setText("تفعيل تسجيل الدخول");login.setChecked(p.getBoolean("prefLogin",false));r.addView(login);login.setOnCheckedChangeListener((v,c)->p.edit().putBoolean("prefLogin",c).apply());setContentView(r);}
 void add(LinearLayout r,String hint,String key,SharedPreferences p){EditText e=new EditText(this);e.setHint(hint);e.setText(p.getString(key,""));r.addView(e);e.setOnFocusChangeListener((v,f)->{if(!f)p.edit().putString(key,e.getText().toString()).apply();});}
}